INSERT INTO feature VALUES('data-parameters','types','Parameterised data families','nominal-data','implemented','ordinary',NULL,'A data family takes parameters; a constructor written as a family argument is typed by the family''s place, and one written as a call''s argument by the parameter it is passed to, the parameters before it that type names replaced by the arguments written for them, a refused declaration''s parameters typing none; one a typed `let` binds by the `let`''s stated type, and one ending a lambda that `return` returns by the codomain of the value function space the body answers; one ending a body whose result is a definition''s application is typed through the definition''s body; at a place the family declares a universe, a name is the type''s, even where a constructor shares it; and a family applied where a value is read, passed for a type parameter or defined as a `Type`, is the family''s type over its arguments.','core-checker kernel-core surface-lowering','corpus/model/data/family-argument.gandr corpus/model/data/data-maybe.gandr corpus/model/data/argument-classifier.gandr corpus/pathological/data/argument-classifier.gandr corpus/model/data/answered-definition.gandr corpus/pathological/data/answered-definition.gandr corpus/pathological/data/refused-callee.gandr corpus/model/data/applied-type-argument.gandr corpus/model/data/index-telescope.gandr','corpus/model/data/family-argument.gandr',NULL);
